For {{ZSTD}}, I used different compression levels (from -7 to 3). 

The {{ZSTD}} shows promising results. The compression level is still good, but the pack/unpack time is lower and uses less CPU time.

I’ll try to support {{ZSTD}} in the {{StaleCache}} as the compression option.

*Benchmark code*

{code:javascript}import { pack, unpack } from "msgpackr";
import snappy from "snappy";
import lz4 from "lz4";
import zlib from "node:zlib";
import zstd from "@toondepauw/node-zstd";

const sampleData = Array.from({ length: 30 }, (_, i) => ({
    cid: i + 16547,
    wd: [1, 4],
    cst: 1700000000,
    cend: 1700003600,
    pst: 300,
    pend: 1200,
}));

const getString = () => JSON.stringify(sampleData);
const getBuffer = () => Buffer.from(getString());

const withBench = (fn, iterations = 10000) => {
    const durations = new Array(iterations);
    const cpuUsages = new Array(iterations);
    for (let i = 0; i < iterations; i++) {
        const start = process.hrtime.bigint();
        const startCpu = process.cpuUsage();
        fn();
        const end = process.hrtime.bigint();
        const cpuUsage = process.cpuUsage(startCpu);
        durations[i] = end - start;
        cpuUsages[i] = cpuUsage;
    }
    return {
        min: Math.min(...durations.map(Number)),
        max: Math.max(...durations.map(Number)),
        cpuMin: Math.min(...cpuUsages.map(({ user }) => user)),
        cpuMax: Math.max(...cpuUsages.map(({ user }) => user)),
    };
};

const bufferToJSON = (buffer) => JSON.parse(buffer.toString());
const formatNumber = (number) => String(number ?? 0).padEnd(8, " ");

(async function benchmark() {
    console.log("Starting benchmark...\n");

    const jsonPackResults = withBench(() => JSON.stringify(sampleData));
    const jsonUnpackResults = withBench(() => JSON.parse(getString()));
    const results = [
        [
            "JSON.strigify",
            getBuffer().length,
            jsonPackResults,
            jsonUnpackResults,
        ],
    ];

    // MessagePack
    const packedMsgPack = pack(sampleData);
    const mpPackDuration = withBench(() => pack(sampleData));
    const mpUnpackDuration = withBench(() => unpack(packedMsgPack));
    results.push([
        "MessagePack",
        packedMsgPack.length,
        mpPackDuration,
        mpUnpackDuration,
    ]);

    // JSON + LZ4
    const compressedLZ4 = lz4.encode(getBuffer());
    const lz4PackDuration = withBench(() => lz4.encode(getBuffer()));
    const lz4UpackDuration = withBench(() =>
        bufferToJSON(lz4.decode(compressedLZ4)),
    );
    results.push([
        "JSON + LZ4",
        compressedLZ4.length,
        lz4PackDuration,
        lz4UpackDuration,
    ]);

    // JSON + deflate
    const compressedZlib = zlib.deflateSync(getBuffer());
    const zlibPackDuration = withBench(() => zlib.deflateSync(getBuffer()));
    const zlibUnpackDuration = withBench(() =>
        bufferToJSON(zlib.inflateSync(compressedZlib)),
    );
    results.push([
        "JSON + zlib.deflate",
        compressedZlib.length,
        zlibPackDuration,
        zlibUnpackDuration,
    ]);

    // JSON + gzip
    const gzipCompressed = zlib.gzipSync(getBuffer());
    const gzipPackDuration = withBench(() => zlib.gzipSync(getBuffer()));
    const gzipUnpackDuration = withBench(() =>
        bufferToJSON(zlib.inflateSync(compressedZlib)),
    );
    results.push([
        "JSON + zlib.gzip",
        gzipCompressed.length,
        gzipPackDuration,
        gzipUnpackDuration,
    ]);

    // JSON + broatli
    const broatliCompressed = zlib.brotliCompressSync(getBuffer());
    const broatliPackDuration = withBench(() =>
        zlib.brotliCompressSync(getBuffer()),
    );
    const broatliUnpackDuration = withBench(() =>
        bufferToJSON(zlib.brotliDecompressSync(broatliCompressed)),
    );
    results.push([
        "JSON + zlib.broatli",
        broatliCompressed.length,
        broatliPackDuration,
        broatliUnpackDuration,
    ]);

    // Snappy
    const snappyCompressed = snappy.compressSync(getBuffer());
    const snappyPackDuration = withBench(() =>
        snappy.compressSync(getBuffer()),
    );
    const snappyUnpackDuration = withBench(() =>
        bufferToJSON(snappy.uncompressSync(snappyCompressed)),
    );
    results.push([
        "JSON + Snappy",
        snappyCompressed.length,
        snappyPackDuration,
        snappyUnpackDuration,
    ]);

    // ZSTD
    const runZSTD = (level) => {
        const zstdEncoder = new zstd.Encoder(level);
        const zstdDecoder = new zstd.Decoder();
        const zstdCompressed = zstdEncoder.encodeSync(getBuffer());
        const zstdPackDuration = withBench(() =>
            zstdEncoder.encodeSync(getBuffer()),
        );
        const zstdUnpackDuration = withBench(() =>
            bufferToJSON(zstdDecoder.decodeSync(zstdCompressed)),
        );
        results.push([
            `JSON + ZSTD ${level}`,
            zstdCompressed.length,
            zstdPackDuration,
            zstdUnpackDuration,
        ]);
    };

    runZSTD(-7);
    runZSTD(-3);
    runZSTD(-1);
    runZSTD(1);
    runZSTD(3);

    console.table(
        results.map(([method, size, packTime, unpackTime]) => ({
            Method: method,
            "Size (bytes)": size,
            "Pack time (ns)": `${formatNumber(packTime.min)} - ${formatNumber(packTime.max)}`,
            "Pack CPU time": `${formatNumber(packTime.cpuMin)} - ${formatNumber(packTime.cpuMax)}`,
            "Unpack time (ns)": `${formatNumber(unpackTime.min)} - ${formatNumber(unpackTime.max)}`,
            "Unpack CPU time": `${formatNumber(unpackTime.cpuMin)} - ${formatNumber(unpackTime.cpuMax)}`,
        })),
    );
})();{code}

