*main.go*

{noformat}package main

import (
	"bufio"
	"encoding/csv"
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/sqweek/dialog"
)

type LogEntry struct {
	Time            string // 11:44
	Level           string
	ServiceName     string
	Reason          string
	TriggerValue    string
	Text            string
	Message         string
	Method          string
	Path            string
}
func (l LogEntry) isEmpty() bool {
    return l.Time == "" && l.Level == "" && l.ServiceName == "" && l.Reason == "" &&
     l.TriggerValue == "" && l.Text == "" && l.Message == "" && l.Method == "" &&
     l.Path == ""
}

var (
	warningRegex = regexp.MustCompile(`:warning: WARNING :: (.*?) :: (.*)`)
	errorRegex   = regexp.MustCompile(`:redalert: ERROR :: (.*?) :: (.*)`)
	timeRegex   = regexp.MustCompile(`(\d\d):(\d\d)`)
)

func parseLogFile(filePath string) ([]LogEntry, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	var (
		entries   []LogEntry
		current   *LogEntry
	)
    isPrevLineTrigger := false
    isPrevWarringErrorLine := false
    current = &LogEntry{}

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
        if skipLine(line) {
            continue
        }
		if isTimeLine(line) {
		    if !current.isEmpty() {
                entries = append(entries, *current)
                current = &LogEntry{
                    Time: line,
                }
            }
		}
        if (isPrevLineTrigger) {
            isPrevLineTrigger = false
            current.Text = line
            continue
        }

        if ok, path := isPathLine(line); ok {
            current.Path = path
            continue
        }
        if ok, method := isMethodLine(line); ok  {
            current.Method = method
            continue
        }
        if ok, message := isMessageLine(line); ok {
            current.Message = message
            continue
        }
        if isPrevWarringErrorLine {
            current.TriggerValue = line
            isPrevWarringErrorLine = false
            isPrevLineTrigger = true
            continue
        }

        if ok, level, serviceName, reason := isWarringErrorLine(line); ok {
            current.Level = level
            current.ServiceName = serviceName
            current.Reason = reason
            isPrevWarringErrorLine = true
            continue
        }
	}

	return entries, scanner.Err()
}

func isMessageLine(line string) (bool, string) {
    if strings.HasPrefix(line, "message: ") {
        return true, strings.TrimPrefix(line, "message: ")
    }
    return  false, ""
}
func isPathLine(line string) (bool, string) {
    if strings.HasPrefix(line, "path: ") {
        return true, strings.TrimPrefix(line, "path: ")
    }
    return  false, ""
}


func isMethodLine(line string) (bool, string) {
    if strings.HasPrefix(line, "method: ") {
        return true, strings.TrimPrefix(line, "method: ")
    }
    return  false, ""
}

func isTimeLine(line string) bool {
    return timeRegex.MatchString(line)
}

func isWarringErrorLine(line string) (bool, string, string, string) {
    if strings.Contains(line, ":warning: WARNING ::") {
        matches := warningRegex.FindStringSubmatch(line)
        if len(matches) == 3 {
            return true, "WARNING", matches[1], matches[2]
        }
    } else if strings.Contains(line, ":redalert: ERROR ::") {
        matches := errorRegex.FindStringSubmatch(line)
        if len(matches) == 3 {
            return true, "ERROR", matches[1], matches[2]
        }
    }
    return false, "", "", ""
}

func skipLine(line string) bool {
    return line == "" || strings.HasPrefix(line, "APP") || strings.HasPrefix(line, "alerter") || strings.HasPrefix(line, ":solved:")
}


func saveToCSV(entries []LogEntry, savePath string) error {

	file, err := os.Create(savePath)
	if err != nil {
		return err
	}
	fmt.Println("file created")

	defer file.Close()

	writer := csv.NewWriter(file)
	defer writer.Flush()

	writer.Write([]string{"Time", "Level", "ServiceName", "Reason", "TriggerValue", "Text", "Message", "Method", "Path"})
	for id, entry := range entries {
	    if id %10 == 1 {
	        fmt.Println("writing: ", id)
	    }
		writer.Write([]string{
		entry.Time,
		entry.Level,
		entry.ServiceName,
		entry.Reason,
		entry.TriggerValue,
		entry.Text,
		entry.Message,
		entry.Method,
		entry.Path,
		})
	}
	fmt.Println("Done!")


	return nil
}

func main() {
	filePath, err := dialog.File().Title("Open Log File").Load()
	if err != nil {
		fmt.Println("Error selecting file:", err)
		return
	}

	entries, err := parseLogFile(filePath)
	if err != nil {
		fmt.Println("Error parsing file:", err)
		return
	}
    fmt.Println("result: ", len(entries), "objects")

	err = saveToCSV(entries, "output.csv")
	if err != nil {
		fmt.Println("Error saving CSV:", err)
	}
}{noformat}

